// ── Audio (Web Audio API, no external files) ──────────────────────────────
let _ac = null;
const getAC = () => { if (!_ac) _ac = new (window.AudioContext||window.webkitAudioContext)(); return _ac; };
const tone = (freq, dur, type="sine", vol=0.18, delay=0) => {
  try {
    const ctx=getAC(), o=ctx.createOscillator(), g=ctx.createGain();
    o.connect(g); g.connect(ctx.destination);
    o.type=type; o.frequency.value=freq;
    const t=ctx.currentTime+delay;
    g.gain.setValueAtTime(0,t);
    g.gain.linearRampToValueAtTime(vol,t+0.02);
    g.gain.exponentialRampToValueAtTime(0.001,t+dur);
    o.start(t); o.stop(t+dur+0.05);
  } catch(e) {}
};
const sfx = {
  card:    () => { tone(523,.35,"triangle",.22); tone(659,.28,"triangle",.16,.08); tone(784,.2,"triangle",.12,.18); },
  hover:   () => tone(440,.1,"sine",.06),
  click:   () => tone(480,.09,"sine",.14),
  menu:    () => { tone(360,.1,"sine",.09); tone(480,.09,"sine",.06,.08); },
  reveal:  () => [330,415,523].forEach((f,i) => tone(f,.4,"triangle",.09-i*.02,i*.1)),
  diceRoll:() => { for(let i=0;i<10;i++) tone(80+Math.random()*120,.05,"sawtooth",.11,i*.07); },
  diceLand:(v) => { tone(180+v*30,.4,"triangle",.2); tone((180+v*30)*1.5,.25,"triangle",.1,.12); },
  trans:   () => [110,138,165].forEach((f,i) => tone(f,.6,"sine",.07,i*.12)),
};

// ── Background themes (matching card palettes) ────────────────────────────
const THEMES = {
  title:   { a:[14,12,22],   b:[22,18,36],   c:[10,8,18]    },
  forest:  { a:[28,52,40],   b:[40,68,52],   c:[20,38,30]   },
  forge:   { a:[38,28,18],   b:[58,42,22],   c:[24,18,10]   },
  throne:  { a:[44,38,18],   b:[62,52,24],   c:[26,22,10]   },
  library: { a:[22,30,44],   b:[30,40,58],   c:[14,20,32]   },
  mist:    { a:[32,28,42],   b:[44,38,56],   c:[20,18,30]   },
  dusk:    { a:[42,28,22],   b:[58,38,28],   c:[28,18,14]   },
  dawn:    { a:[24,36,46],   b:[34,50,62],   c:[16,26,36]   },
};
const lerp  = (a,b,t) => a.map((v,i) => Math.round(v+(b[i]-v)*t));
const rgb   = c => `rgb(${c[0]},${c[1]},${c[2]})`;

// ── Background Canvas ─────────────────────────────────────────────────────
function Background({ theme }) {
  const ref   = useRef();
  const cur   = useRef(THEMES.title);
  const tgt   = useRef(THEMES.title);
  const prog  = useRef(1);
  const time  = useRef(0);
  const rafId = useRef();

  useEffect(() => { tgt.current = THEMES[theme]||THEMES.title; prog.current = 0; }, [theme]);

  useEffect(() => {
    const canvas = ref.current;
    const ctx    = canvas.getContext("2d");
    let pts = [];

    const resize = () => {
      canvas.width  = window.innerWidth;
      canvas.height = window.innerHeight;
      pts = Array.from({length:55},()=>({
        x:Math.random()*canvas.width, y:Math.random()*canvas.height,
        r:Math.random()*130+45, vx:(Math.random()-.5)*.1, vy:-(Math.random()*.07+.02),
        a:Math.random()*.06+.01,
      }));
    };
    resize();
    window.addEventListener("resize", resize);

    const draw = () => {
      const {width:W, height:H} = canvas;
      if (prog.current < 1) prog.current = Math.min(1, prog.current + .007);
      const p = prog.current, e = p<.5?2*p*p:-1+(4-2*p)*p;
      const C = cur.current, T = tgt.current;
      const a = lerp(C.a,T.a,e), b = lerp(C.b,T.b,e), c = lerp(C.c,T.c,e);
      if (p>=1) cur.current = {...T};

      const g = ctx.createLinearGradient(0,0,0,H);
      g.addColorStop(0, rgb(a)); g.addColorStop(.55, rgb(b)); g.addColorStop(1, rgb(c));
      ctx.fillStyle=g; ctx.fillRect(0,0,W,H);

      // Vignette
      const v = ctx.createRadialGradient(W/2,H/2,H*.15,W/2,H/2,H*.85);
      v.addColorStop(0,"rgba(0,0,0,0)"); v.addColorStop(1,"rgba(0,0,0,0.5)");
      ctx.fillStyle=v; ctx.fillRect(0,0,W,H);

      // Fog particles
      const t = time.current;
      pts.forEach(pt => {
        pt.x+=pt.vx; pt.y+=pt.vy;
        if(pt.y+pt.r<0){pt.y=H+pt.r;pt.x=Math.random()*W;}
        if(pt.x<-pt.r)pt.x=W+pt.r;
        if(pt.x>W+pt.r)pt.x=-pt.r;
        const breath=.6+.4*Math.sin(t*.4+pt.x*.01);
        const gp=ctx.createRadialGradient(pt.x,pt.y,0,pt.x,pt.y,pt.r);
        gp.addColorStop(0,`rgba(${b[0]+18},${b[1]+18},${b[2]+18},${pt.a*breath})`);
        gp.addColorStop(1,"rgba(0,0,0,0)");
        ctx.fillStyle=gp; ctx.fillRect(pt.x-pt.r,pt.y-pt.r,pt.r*2,pt.r*2);
      });
      time.current+=.016;
      rafId.current = requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(rafId.current); window.removeEventListener("resize", resize); };
  }, []);

  return <canvas ref={ref} style={{position:"fixed",inset:0,zIndex:0,pointerEvents:"none"}} />;
}

// ── Card Fan ──────────────────────────────────────────────────────────────
function CardFan({ cards, onSelect, locked }) {
  const [hov, setHov] = useState(null);
  const n = cards.length, spread = n<=2?18:n===3?22:26;
  return (
    <div style={{position:"relative",height:310,display:"flex",alignItems:"flex-end",justifyContent:"center",width:"100%",maxWidth:600,margin:"16px auto 80px"}}>
      {cards.map((card,i) => {
        const angle=(i-(n-1)/2)*spread, isHov=hov===i;
        const yBase=Math.pow(Math.abs(angle)/spread,1.4)*18;
        return (
          <div key={card.indexCard}
            onMouseEnter={()=>{ if(!locked){setHov(i);sfx.hover();} }}
            onMouseLeave={()=>setHov(null)}
            onClick={()=>{ if(!locked){sfx.card();onSelect(card);} }}
            style={{
              position:"absolute", bottom:0,
              transform:`rotate(${angle}deg) translateY(${isHov?-42:yBase}px) scale(${isHov?1.07:1})`,
              transformOrigin:"bottom center",
              transition:"transform 0.38s cubic-bezier(0.34,1.45,0.64,1)",
              cursor:locked?"default":"pointer",
              zIndex:isHov?100:10+i,
              display:"flex", flexDirection:"column", alignItems:"center",
            }}>
            {/* Card image */}
            <div style={{
              width:130, height:200, borderRadius:10, overflow:"hidden",
              boxShadow: isHov
                ? "0 30px 65px rgba(0,0,0,0.8), 0 0 0 1px rgba(255,255,255,0.15)"
                : "0 12px 38px rgba(0,0,0,0.7)",
              transition:"box-shadow 0.35s ease", position:"relative",
            }}>
              <img src={card.src} alt={card.textCard} style={{
                width:"100%", height:"100%", objectFit:"cover", display:"block",
                filter: locked&&!isHov?"brightness(0.5)": isHov?"brightness(1.06)":"brightness(0.88)",
                transition:"filter 0.3s ease",
              }}/>
              {isHov && <div style={{position:"absolute",inset:0,background:"linear-gradient(135deg,rgba(255,255,255,0.07) 0%,transparent 55%)",pointerEvents:"none"}}/>}
            </div>
            {/* Hover label */}
            <div style={{
              position:"absolute", bottom:-72, width:170, textAlign:"center", pointerEvents:"none",
              opacity:isHov?1:0, transform:isHov?"translateY(0)":"translateY(8px)",
              transition:"all 0.28s ease",
            }}>
              <p style={{margin:"0 0 3px",color:"#e8dfc8",fontFamily:"Georgia,serif",fontSize:13,letterSpacing:"1.5px",textShadow:"0 1px 8px rgba(0,0,0,0.9)"}}>{card.textCard}</p>
              <p style={{margin:0,color:"#a89870",fontFamily:"Georgia,serif",fontSize:10,fontStyle:"italic",textShadow:"0 1px 5px rgba(0,0,0,0.9)"}}>{card.effectCard}</p>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ── Dice ──────────────────────────────────────────────────────────────────
const DOTS = {1:[[1,1]],2:[[0,0],[2,2]],3:[[0,0],[1,1],[2,2]],4:[[0,0],[0,2],[2,0],[2,2]],5:[[0,0],[0,2],[1,1],[2,0],[2,2]],6:[[0,0],[0,2],[1,0],[1,2],[2,0],[2,2]]};

function DiceFace({v}) {
  const dots = DOTS[v]||[];
  return (
    <div style={{width:100,height:100,background:"linear-gradient(145deg,#d4c9a8,#b5a882)",border:"2px solid #8a7a58",borderRadius:14,display:"grid",gridTemplate:"repeat(3,1fr)/repeat(3,1fr)",padding:12,boxSizing:"border-box",boxShadow:"inset 0 2px 4px rgba(255,255,255,0.35),inset 0 -2px 6px rgba(0,0,0,0.3),0 8px 28px rgba(0,0,0,0.6)"}}>
      {Array.from({length:9},(_,idx)=>{const r=Math.floor(idx/3),c=idx%3,has=dots.some(([dr,dc])=>dr===r&&dc===c);return <div key={idx} style={{display:"flex",alignItems:"center",justifyContent:"center"}}>{has&&<div style={{width:13,height:13,borderRadius:"50%",background:"radial-gradient(circle at 35% 35%,#5a4830,#2a1e0e)",boxShadow:"0 1px 3px rgba(0,0,0,0.5)"}}/>}</div>;})}
    </div>
  );
}

function Dice({ onResult }) {
  const [val,setVal]=useState(null), [rolling,setRolling]=useState(false), [disp,setDisp]=useState(6);
  const roll = () => {
    if(rolling||val!==null) return;
    sfx.diceRoll(); setRolling(true); setVal(null);
    let ticks=0;
    const iv=setInterval(()=>{
      setDisp(Math.ceil(Math.random()*6)); ticks++;
      if(ticks>14){clearInterval(iv);const r=Math.ceil(Math.random()*6);setDisp(r);setVal(r);setRolling(false);sfx.diceLand(r);setTimeout(()=>onResult(r),1400);}
    },55+ticks*4);
  };
  return (
    <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:20}}>
      <div onClick={roll} style={{cursor:rolling||val?"default":"pointer",transform:rolling?"scale(0.9)":val?"scale(1.05)":"scale(1)",transition:"transform 0.5s cubic-bezier(0.34,1.56,0.64,1)"}}><DiceFace v={disp}/></div>
      {val!==null
        ? <p style={{color:"#e8dfc8",fontFamily:"Georgia,serif",fontSize:16,letterSpacing:"1px",textShadow:"0 2px 8px rgba(0,0,0,0.6)"}}>Il fato ha parlato: <span style={{fontSize:28,color:"#c8a84b",textShadow:"0 0 18px rgba(200,168,75,0.5)"}}>{val}</span></p>
        : <button onClick={roll} disabled={rolling} style={{background:"transparent",border:"1px solid rgba(200,168,75,0.4)",color:"#c8a84b",padding:"12px 44px",fontFamily:"Georgia,serif",letterSpacing:"4px",fontSize:11,cursor:rolling?"not-allowed":"pointer",opacity:rolling?.5:1,textTransform:"uppercase"}}>Lancia il Dado</button>
      }
    </div>
  );
}

